 WorkRequest metadata;Digest source{};vxnn::EvidenceScope scope=vxnn::EvidenceScope::HOST_PROTOCOL_TEST;uint32_t cookie_ns=0;uint64_t budget=0;Int16TraceSink trace;Int16OutputSink publish;Int16RequestReceipt receipt;bool active=false;
